 $('neighborhood-connections').innerHTML=n.records.length?n.records.map(r=>`<article class="neighborhood-record"><strong>${esc(sourceName(r.a))} ↔ ${esc(sourceName(r.b))}</strong><small>${esc(r.level)} · source evidence</small><div><button data-select="record:${esc(r.id)}" data-neighborhood-evidence>Evidence</button>${[...new Set([r.a,r.b])].map(id=>`<button data-neighborhood="${esc(id)}">Explore ${esc(sourceName(id))}</button>`).join('')}</div><div>${[...new Set([r.a,r.b])].map(endpoint=>{const rows=sites.filter(v=>v.record===r.id&&v.endpoint===endpoint);return rows.length?rows.map(v=>`<button class="neighborhood-site" data-neighborhood-site="${esc(v.region.id)}" data-site-record="${esc(r.id)}" data-site-endpoint="${esc(endpoint)}">${esc(sourceName(endpoint))} · ${esc(v.region.kind)} ${v.region.start}–${v.region.end}</button>`).join(''):`<button data-neighborhood-unresolved="${esc(r.id)}" data-site-endpoint="${esc(endpoint)}">${esc(sourceName(endpoint))} · site unresolved</button>`;}).join('')}</div></article>`).join(''):'<p>No qualified supported pair is assigned to this selected reference. Its retained fold/coordinate hold remains visible.</p>';
 $('neighborhood-context').innerHTML=n.otherRecords.map(r=>`<p>${esc(sourceName(r.a))} ↔ ${esc(sourceName(r.b))} · ${esc(r.level)}</p><button data-select="record:${esc(r.id)}" data-neighborhood-evidence>Inspect context evidence — not a supported-pair edge</button>`).join('')+n.holds.map(h=>`<p class="limit">${esc(h.reason)}</p><button data-neighborhood="${esc(h.sourceEndpoint)}">Open separate source neighborhood — mapping held</button>`).join('')+'<p>Separate published-source neighborhoods; not assigned to this retained protein:</p>'+[...new Set(supportedAcrossPairs(data).flatMap(r=>[r.a,r.b]))].map(id=>`<button data-neighborhood="${esc(id)}">${esc(sourceName(id))} · source endpoint</button>`).join('');
 $('protein-neighborhood').dataset.neighborhoodState=JSON.stringify({seed:n.seed.id,proteins:n.proteins.map(p=>p.id),records:n.records.map(r=>r.id),partners:n.partners,references:n.references.map(l=>l.id),otherRecords:n.otherRecords.map(r=>r.id),sites:sites.map(v=>({record:v.record,endpoint:v.endpoint,annotation:v.region.id,category:v.region.category,residues:v.region.correspondence.length})),holds:n.holds.length});
