 if(!neighborhood||!proteinNeighborhood(data,neighborhood).records.some(r=>r.id===record))return;document.querySelector('main').classList.remove('library-open','evidence-open');openInteraction(record);if(!lensState)return;lensState.endpoint=endpoint;lensState.region=region;$('lens-endpoint').value=endpoint;showInteractionSelection();if(index!==null)interactionLens?.selectResidue(index);
