function openProteinLens(id){if(atomicActive)closeAtomic();if(!renderer||!data.shape_traces[id])return;if(lensState)closeInteraction();if(context.kind!=='network')enter('network');lensWasWide=document.querySelector('main').classList.contains('wide-view');lensState={kind:'protein',endpoint:id,record:null,region:null};document.querySelector('main').classList.add('wide-view');$('wide-view').textContent='Show panels';$('wide-view').setAttribute('aria-pressed','true');document.querySelector('.workspace').classList.add('interaction-mode');$('interaction-dock').hidden=false;document.querySelector('.view-panes').classList.add('lens-open');for(const key of ['lens-record','lens-endpoint','lens-region','lens-optional'])$(key).parentElement.hidden=true;document.querySelector('#interaction-dock h2').textContent='Protein inspection';inspect('protein',id);showProteinLens();resize();fit(true);}

