function sourceLinks(ids){return `<details><summary>Source references · ${ids.length}</summary>${ids.map(id=>{const s=by(data.sources,id);return s?`<div class="source"><a target="_blank" rel="noreferrer" href="${esc(s.url)}">${esc(s.title)}</a><p>${esc(s.year)} · ${esc(s.evidence_note)}</p></div>`:''}).join('')}</details>`;}
