 if(kind==='object'){
  const names={blue:['Blue pen','Barrel, refill, grip, tip and cap share the same object frame.','pen:blue'],amber:['Amber pen','Another pen demonstrates independent placement in the same reference space.','pen:blue'],mug:['Ceramic mug','Designed open vessel, rim, handle and liquid surface.'],notebook:['Notebook','A designed cover, page block and printed lines.'],cell:['Schematic cell','A membrane-like boundary, nucleus, internal tubules and organelle-like forms.','cell:cell']};
  const n=names[id]||[id,'Designed component in the current local reference frame.'];html=`<span class="badge warm">DESIGNED PRACTICE FORM</span><h2>${esc(n[0])}</h2><p>${esc(n[1])}</p>${n[2]?`<button class="enter" data-enter="${n[2]}">Look inside →</button>`:''}<p class="limit">Illustrative geometry and chosen dimensions. No material behavior, biology or measured construction is inferred.</p>`;
 }
