 if(focus){if(kind==='group'&&(context.kind==='organism'||showAllForms()||context.kind==='network')){const boxes=system(id).members.map(id=>sceneObjects.get('protein:'+id)).filter(Boolean),box=new T.Box3();boxes.forEach(obj=>box.union(new T.Box3().setFromObject(obj)));if(boxes.length)focusBounds(box);}else{const obj=sceneObjects.get(kind+':'+id);if(obj)focusObject(obj);}}
